import{_ as o,a0 as s,w as d,s as l,ao as p,I as n,x as r,a1 as e,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"修复 Arch Linux 中的 “invalid or corrupted package (PGP signature)” 错误 | LCTT x X-CMD","titleTemplate":false,"description":"修复 Arch Linux 中的 “invalid or corrupted package (PGP signature)” 错误 | LCTT (202306) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"修复 Arch Linux 中的 “invalid or corrupted package (PGP signature)” 错误 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"修复 Arch Linux 中的 “invalid or corrupted package (PGP signature)” 错误 | LCTT (202306) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202306/20230520.0 ⭐️ Fix “invalid or corrupted package (PGP signature)” Error In Arch Linux","title":"修复 Arch Linux 中的 “invalid or corrupted package (PGP signature)” 错误","tag":"202306","desc":""},"relativePath":"202306/20230520.0 ⭐️ Fix “invalid or corrupted package (PGP signature)” Error In Arch Linux.md","filePath":"[post].md"}'),u={name:"202306/20230520.0 ⭐️ Fix “invalid or corrupted package (PGP signature)” Error In Arch Linux.md"};function g(c,i,h,k,x,m){const a=s("Link");return d(),l("div",null,[i[20]||(i[20]=p('<h1 id="修复-arch-linux-中的-invalid-or-corrupted-package-pgp-signature-错误" tabindex="-1">修复 Arch Linux 中的 “invalid or corrupted package (PGP signature)” 错误 <a class="header-anchor" href="#修复-arch-linux-中的-invalid-or-corrupted-package-pgp-signature-错误" aria-label="Permalink to “修复 Arch Linux 中的 “invalid or corrupted package (PGP signature)” 错误”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202306/03/231559qweqmphmmzpwxhiq.jpg" alt=""></p><blockquote><p>修复 Arch Linux 中 “invalid or corrupted package” 错误的简单指南。</p></blockquote><p>我在物理机和虚拟机中都安装有一些 Arch Linux 系统，我会在需要时访问它们。将近两个月后，当我尝试使用 <code>sudo pacman -Syu</code> 升级其中一个中的 Arch Linux 时，我遇到了数百个这样的错误：</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/05/Sample-invalid-or-corrupted-package-error-in-Arch-Linux.jpg" alt="Arch Linux 中无效或损坏的包错误示例"></p><p>问题是当你遇到上面的错误时，你无法升级/更新你的 Arch 系统。即使你同步镜像或获得更快的镜像。所以，如果你运行 <code>sudo pacman -Syyu</code>，错误仍然存在。这就造成了困难，因为在修复此问题之前你无法安装任何其他软件包。</p><h3 id="原因" tabindex="-1">原因 <a class="header-anchor" href="#原因" aria-label="Permalink to “原因”">​</a></h3><p>当你在 Arch Linux 系统上安装或升级软件包时，pacman 会根据 <code>archlinux-keyring</code> 软件包中的密钥检查软件包的数字签名。此验证过程可确保你下载和安装的软件包未经修改且来自受信任的来源。</p>',8)),n("p",null,[i[1]||(i[1]=r("它包含用于 ",-1)),e(a,{href:"https://wiki.archlinux.org/title/Pacman/Package_signing"},{default:t(()=>[...i[0]||(i[0]=[r("验证包的真实性和完整性",-1)])]),_:1}),i[2]||(i[2]=r(" 和 pacman 中的密钥环。",-1)),i[3]||(i[3]=n("code",null,"archlinux-keyring",-1)),i[4]||(i[4]=r(" 包由 Arch Linux 开发人员定期更新，以包含新的可信密钥并撤销任何泄露的密钥。",-1))]),i[21]||(i[21]=p('<p>如果你的 Arch Linux 系统很长时间没有更新，那么各种包的数字签名可能会不匹配。更改后的密钥可能与你系统中的密钥不匹配。</p><p>因此出现错误了。</p><h3 id="修复" tabindex="-1">修复 <a class="header-anchor" href="#修复" aria-label="Permalink to “修复”">​</a></h3><p>要修复 Arch Linux 中的 “invalid or corrupted package (PGP signature)” 错误，你需要从 <code>Core</code> 仓库安装/更新 <code>archlinux-keyring</code> 包。从终端运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -S archlinux-keyring</span></span></code></pre></div><p>上述命令完成后，运行升级：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -Syu</span></span></code></pre></div><p>这将解决问题，你可以在 Arch Linux 中继续你的正常活动。建议始终保持 <code>archlinux-keyring</code> 包为最新，以维护 Arch Linux 系统的安全性和完整性。</p><p><em>（题图：MJ/7ed6d549-93c6-463d-823e-3a8c3957790f）</em></p><hr>',10)),n("p",null,[i[6]||(i[6]=r("via: ",-1)),e(a,{href:"https://www.debugpoint.com/invalid-corrupted-package-arch/"},{default:t(()=>[...i[5]||(i[5]=[r("https://www.debugpoint.com/invalid-corrupted-package-arch/",-1)])]),_:1})]),n("p",null,[i[11]||(i[11]=r("作者：",-1)),e(a,{href:"https://www.debugpoint.com/author/admin1/"},{default:t(()=>[...i[7]||(i[7]=[r("Arindam",-1)])]),_:1}),i[12]||(i[12]=r(" 选题：",-1)),e(a,{href:"https://github.com/lkxed/"},{default:t(()=>[...i[8]||(i[8]=[r("lkxed",-1)])]),_:1}),i[13]||(i[13]=r(" 译者：",-1)),e(a,{href:"https://github.com/geekpi"},{default:t(()=>[...i[9]||(i[9]=[r("geekpi",-1)])]),_:1}),i[14]||(i[14]=r(" 校对：",-1)),e(a,{href:"https://github.com/wxy"},{default:t(()=>[...i[10]||(i[10]=[r("wxy",-1)])]),_:1})]),n("p",null,[i[17]||(i[17]=r("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...i[15]||(i[15]=[r("LCTT",-1)])]),_:1}),i[18]||(i[18]=r(" 原创编译，",-1)),e(a,{href:"https://linux.cn/"},{default:t(()=>[...i[16]||(i[16]=[r("Linux中国",-1)])]),_:1}),i[19]||(i[19]=r(" 荣誉推出",-1))])])}const b=o(u,[["render",g]]);export{L as __pageData,b as default};
